  ENVIAR_URL: 'http://localhost:5678/webhook/horizon-agente-enviar',
  TELEGRAM_TOKEN: '',                                 // opcional: aviso de borradores a tu Telegram
  TELEGRAM_CHAT_ID: '',
} }];

const q = $input.first().json.query || {};
const cfg = $('Config verificación').first().json;
return [{ json: { body: q['hub.verify_token'] === cfg.VERIFY_TOKEN ? (q['hub.challenge'] || '') : 'forbidden' } }];

// ⚙️ Configuración — completa estos valores una sola vez
return [{ json: {
  HORIZON_URL: 'https://www.horizonweb.cl',            // cerebro del agente
  BOT_SECRET: 'PEGAR_HORIZON_BOT_SECRET',             // igual al de Vercel
  VERIFY_TOKEN: 'horizon_verify_2026',                // el mismo que pones en Meta al suscribir el webhook
  ENVIAR_URL: 'http://localhost:5678/webhook/horizon-agente-enviar',
  TELEGRAM_TOKEN: '',                                 // opcional: aviso de borradores a tu Telegram
  TELEGRAM_CHAT_ID: '',
} }];

// Normaliza mensajes de WhatsApp Cloud API e Instagram (Messaging API) a un formato único
const body = $('Mensaje entrante').first().json.body || {};
const out = [];
for (const entry of body.entry || []) {
  // WhatsApp
  for (const ch of entry.changes || []) {
    const v = ch.value || {};
    const contacto = (v.contacts || [])[0];
    for (const m of v.messages || []) {
      if (m.type !== 'text') continue; // audios, fotos, stickers: los ve Benjamín en la app
      out.push({ json: { canal: 'whatsapp', contacto_id: m.from, nombre: contacto?.profile?.name || '', texto: m.text?.body || '', mensaje_id: m.id } });
    }
  }
  // Instagram
  for (const ev of entry.messaging || []) {
    const m = ev.message;
    if (!m || m.is_echo || !m.text) continue; // ignora lo que enviamos nosotros
    out.push({ json: { canal: 'instagram', contacto_id: String(ev.sender.id), nombre: '', texto: m.text, mensaje_id: m.mid } });
  }
}
return out;
